describe('Inline Editing on Table Row', () => {
    beforeEach(() => {
        cy.visit('/your-table-page-url'); // Replace with your actual URL
    });

    it('should allow inline editing of a table row', () => {
        cy.get('table tbody tr').first().find('td').first().dblclick(); // Double-click to edit
        cy.get('input').clear().type('New Value'); // Assuming the input appears for editing
        cy.get('input').blur(); // Trigger save on blur
        cy.get('table tbody tr').first().find('td').first().should('contain', 'New Value'); // Verify the new value
    });

    it('should not save changes if input is empty', () => {
        cy.get('table tbody tr').first().find('td').first().dblclick(); // Double-click to edit
        cy.get('input').clear(); // Clear the input
        cy.get('input').blur(); // Trigger save on blur
        cy.get('table tbody tr').first().find('td').first().should('not.contain', ''); // Verify the cell is not empty
    });
});
